#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string s;
    cin >> N >> s;

    int longest = 1;

    for (int center = 0; center < N; ++center) {
        int left = center, right = center;
        while (left >= 0 && right < N && s[left] == s[right]) {
            longest = max(longest, right - left + 1);
            --left;
            ++right;
        }

        left = center;
        right = center + 1;
        while (left >= 0 && right < N && s[left] == s[right]) {
            longest = max(longest, right - left + 1);
            --left;
            ++right;
        }
    }

    cout << longest << '\n';
    return 0;
}
